service.method:

SELECT
	APP_USER_ID AS ID
	, #DB_OWNER#GETUSERNAME(HOUSE_CODE, COMPANY_CODE, APP_USER_ID, 'KO') AS NAME
	, #DB_OWNER#GETUSEREMAIL(HOUSE_CODE, COMPANY_CODE, APP_USER_ID, 'KO') AS MAIL
FROM SGWLN
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
  AND COMPANY_CODE = ${session.COMPANY_CODE}
  AND APP_NO = ${APP_NO}
  AND APP_NO_SEQ = ${APP_NO_SEQ}
  AND APP_LINE_STATUS = 'L04'


UPDATE SSIPD
   SET KEY_VALUE = ${KEY_VALUE}
     , OBJ_CODE = ${OBJ_CODE}
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER = ${DOC_NO}


    SELECT
          KEY_VALUE
         ,OBJ_CODE
      FROM SSIPD
	 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	   AND COMPANY_CODE = ${session.COMPANY_CODE}
	   AND SMR_NUMBER = ${SMR_NUMBER}
